/* global WebSocket, FileReader, Blob, fetch */
import assert from 'node:assert/strict';
import { once } from 'node:events';
import { connect } from 'node:net';
import { readFile } from 'node:fs/promises';
import { WebSocket as Peer, WebSocketServer } from 'ws';

// The Rust acceptance test owns the loopback Host and verifies its persisted
// receipt hashes against independently generated bytes. No model is attached.
const { chromium } = await import(process.env.PLAYWRIGHT_MODULE || 'playwright');
const hostPort = Number(process.env.ATTACHMENT_TEST_HOST_PORT);
const origin = process.env.COMPOSER_TEST_ORIGIN || 'http://127.0.0.1:1430';
const relayFile = process.env.ATTACHMENT_TEST_RELAY_CONFIG;
const cloud = relayFile ? JSON.parse(await readFile(relayFile, 'utf8')) : undefined;
assert(Number.isInteger(hostPort) && hostPort > 0);
assert.equal(new URL(origin).hostname, '127.0.0.1');
if (cloud) assert.match(cloud.origin, /^http:\/\/127\.0\.0\.1:\d+$/);

const peers = [];
let browser, gateway;
let maxFrame = 0;
const bridgeHost = (socket) => {
  const stream = connect(hostPort, '127.0.0.1');
  peers.push(() => stream.destroy());
  socket.on('message', (bytes, binary) => {
    assert(binary && bytes.length <= 65536);
    maxFrame = Math.max(maxFrame, bytes.length);
    stream.write(bytes);
  });
  stream.on('data', (bytes) => {
    if (socket.readyState === Peer.OPEN) socket.send(bytes);
  });
  stream.on('error', () => socket.close());
  stream.on('close', () => socket.close());
  socket.on('close', () => stream.destroy());
};
try {
  let uplink;
  if (cloud) {
    const endpoint = cloud.origin.replace('http:', 'ws:') + '/api/v1/relay';
    const peer = (path, token, ticket) => {
      const headers = { authorization: 'Bearer ' + token };
      if (ticket) headers['x-tunnel-ticket'] = ticket;
      const socket = new Peer(endpoint + path, { headers, maxPayload: 65536 });
      peers.push(() => socket.terminate());
      return socket;
    };
    const control = peer('/control', cloud.desktop);
    const [ready] = await once(control, 'message');
    assert.equal(JSON.parse(ready).hostId, cloud.hostId);
    const offer = once(control, 'message');
    const response = await fetch(cloud.origin + '/api/v1/relay/tunnels', {
      method: 'POST',
      headers: { authorization: 'Bearer ' + cloud.mobile, 'content-type': 'application/json' },
      body: JSON.stringify({ hostId: cloud.hostId }),
    });
    assert.equal(response.status, 200);
    const { tunnelId, clientTicket } = await response.json();
    const invitation = JSON.parse((await offer)[0]);
    assert.equal(invitation.tunnelId, tunnelId);
    const host = peer('/tunnels/' + tunnelId + '/host', cloud.desktop, invitation.hostTicket);
    bridgeHost(host);
    uplink = peer('/tunnels/' + tunnelId + '/client', cloud.mobile, clientTicket);
    await Promise.all([once(host, 'open'), once(uplink, 'open')]);
  }
  gateway = new WebSocketServer({ host: '127.0.0.1', port: 0, maxPayload: 65536 });
  await once(gateway, 'listening');
  gateway.on('connection', (socket) => {
    if (!uplink) return bridgeHost(socket);
    socket.on('message', (data) => uplink.send(data));
    uplink.on('message', (data) => socket.send(data));
  });
  browser = await chromium.launch({
    headless: true,
    executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE,
  });
  const page = await browser.newPage();
  // Use an actual loopback response so Chromium classifies this document's
  // network address space correctly. This static resource starts no app.
  await page.goto(origin + '/@vite/client');
  const results = await page.evaluate(
    async ({ pin, credential, url }) => {
      const { HostSocket } = await import('/src/transport/host.ts');
      const { connectPinnedTls } = await import('/src/transport/tls.ts');
      const outer = new WebSocket(url);
      outer.binaryType = 'arraybuffer';
      await new Promise((resolve, reject) => {
        outer.onopen = resolve;
        outer.onerror = () => reject(new Error('Could not open the loopback byte gateway'));
      });
      const tls = await connectPinnedTls(
        {
          send: (bytes) => outer.send(bytes),
          close: () => outer.close(),
          receive(handler, end) {
            outer.onmessage = (e) => handler(new Uint8Array(e.data));
            outer.onclose = () => end(new Error('Tunnel closed'));
          },
        },
        pin,
      );
      const socket = await HostSocket.upgrade(tls, credential);
      const pending = new Map();
      void socket.receive(
        (text) => {
          const message = JSON.parse(text);
          if (message.id) pending.get(message.id)?.resolve(message);
        },
        (error) => {
          for (const wait of pending.values()) wait.reject(error);
        },
      );
      const call = async (id, action, payload) => {
        const answer = new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
        const timeout = setTimeout(
          () => pending.get(id)?.reject(new Error('Host response timed out')),
          20000,
        );
        try {
          await socket.send(JSON.stringify({ v: 1, type: 'request', id, action, payload }));
          return await answer;
        } finally {
          clearTimeout(timeout);
          pending.delete(id);
        }
      };
      const hello = await call('hello', 'system.hello', {
        client: 'AgentDeck Web/0.3.0',
        version: 1,
      });
      if (hello.type !== 'response') throw new Error('Host handshake failed');
      const results = [];
      for (const over of [false, true]) {
        const bytes = Uint8Array.from(
          { length: 2 * 1024 * 1024 + Number(over) },
          (_, i) => i % 251,
        );
        const data = await new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(String(reader.result).split(',')[1]);
          reader.onerror = reject;
          reader.readAsDataURL(new Blob([bytes]));
        });
        for (const action of ['turn.start', 'queue.add']) {
          const payload = {
            sessionId: 'transport-test',
            text: 'boundary',
            attachments: [{ name: 'bound.bin', data }],
          };
          const reply = await call(action + (over ? '-over' : ''), action, payload);
          results.push({
            action,
            over,
            code: reply.code,
            queued: reply.payload?.result?.queuedSubmission?.id,
          });
        }
      }
      socket.close();
      return results;
    },
    {
      pin: process.env.ATTACHMENT_TEST_PIN,
      credential: process.env.ATTACHMENT_TEST_GRANT,
      url: 'ws://127.0.0.1:' + gateway.address().port,
    },
  );
  for (const { action, code, over, queued } of results) {
    if (over) assert.equal(code, 'INVALID_REQUEST');
    else if (action === 'queue.add') assert.equal(queued, 'queued-bound', code);
    else assert.equal(code, 'UPSTREAM_ERROR', 'The isolated peer refuses turn execution');
  }
  assert(maxFrame > 0 && maxFrame <= 65536);
  console.log(
    '2 MiB authenticated send and queue payloads reached Rust Host; +1 byte rejected. Relay:',
    cloud ? 'Rust Cloud' : 'local byte gateway',
    'largest frame:',
    maxFrame,
  );
} finally {
  await browser?.close();
  for (const peer of peers) peer();
  for (const socket of gateway?.clients || []) socket.terminate();
  if (gateway) await new Promise((resolve) => gateway.close(resolve));
}
